// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.conversationimport timber.log.Timberimport com.roshan.persona.voice.capture.AudioCapturePipeline/** * NOUS — End-of-Speech Predictor (§12 + §17 v2 Fix #2). * * Predicts whether the user is about to stop speaking — *before* they * actually stop — so the Brain can start processing the utterance early. * This is the key to NOUS's < 100 ms response latency (§17 Impact). * * ## Two-tier architecture (v2 fix #2) * * ``` * Tier 1: VAP ML Model (primary)        — 95% accuracy, ~100 ms latency *   "Voice Activity Projection" — a small ONNX model (20 MB) that takes *   3 s of audio context and outputs P(user stops within 1 s). * * Tier 2: Heuristic Fallback (always available) *   Combines 4 signals (§12 End-of-Speech Prediction): *     - Intonation drop  (falling pitch = statement ending)         30 % *     - Rate slowdown    (people slow down at end)                  20 % *     - Filler words     ("so...", "that's it...")                  20 % *     - Silence duration (200 ms+ = likely end)                     30 % *   Score > 0.6 → predict end-of-speech. * ``` * * ## Why two tiers (§17) * * v1 used only heuristics — 75 % accuracy, false positives on mid-sentence * pauses (user thinking), false negatives on rapid turn-taking. v2 adds * the VAP ML model for 95 % accuracy. The heuristic remains as a fallback * for devices that can't run the 20 MB ONNX model, and as a tiebreaker * when VAP confidence is borderline. * * ## Integration * * The [ConversationEngine] (Step 5.9 source 2) calls [predictEndOfSpeech] * on every audio chunk while the user is speaking. When the prediction * flips to `willEndWithin1Second = true`, the Brain is told to start * processing the partial transcript early. The Brain's response is ready * by the time the user actually stops → < 100 ms perceived latency. * * ## Testability * * [VapBackend] is an interface — tests inject a fake. The heuristic path * is fully testable in pure Kotlin (no native deps). [AudioFeatures] is * a plain data class so tests can construct any feature combination. * * @see <a href="docs/strategy/module-5-strategy-v2.md">§12 Conversation Engine, §17 VAP End-of-Speech Prediction</a> */class EndOfSpeechPredictor(    private val vapBackend: VapBackend?,    internal val config: Config = Config(),) {    /**     * Configuration for the end-of-speech predictor.     *     * @param vapConfidenceThreshold  VAP probability above which we predict     *                                end-of-speech (default 0.7 per §17).     * @param heuristicThreshold      Heuristic score above which we predict     *                                end-of-speech (default 0.6 per §12).     * @param silenceMsForEnd         Silence duration that strongly indicates     *                                end-of-turn (default 500 ms per §6 STT).     * @param contextSeconds          Audio context window length (3 s per §17).     */    data class Config(        val vapConfidenceThreshold: Float = DEFAULT_VAP_THRESHOLD,        val heuristicThreshold: Float = DEFAULT_HEURISTIC_THRESHOLD,        val silenceMsForEnd: Long = DEFAULT_SILENCE_MS,        val contextSeconds: Int = DEFAULT_CONTEXT_SECONDS,    ) {        init {            require(vapConfidenceThreshold in 0f..1f) {                "vapConfidenceThreshold must be in [0,1], got $vapConfidenceThreshold"            }            require(heuristicThreshold in 0f..1f) {                "heuristicThreshold must be in [0,1], got $heuristicThreshold"            }            require(silenceMsForEnd > 0) { "silenceMsForEnd must be positive" }            require(contextSeconds in 1..10) { "contextSeconds must be 1..10" }        }        companion object {            const val DEFAULT_VAP_THRESHOLD = 0.7f            const val DEFAULT_HEURISTIC_THRESHOLD = 0.6f            const val DEFAULT_SILENCE_MS = 500L            const val DEFAULT_CONTEXT_SECONDS = 3        }    }    /**     * Predict whether the user will stop speaking within 1 second.     *     * @param audioContext  recent audio (last [Config.contextSeconds] seconds,     *                       16 kHz 16-bit PCM). Should be at least 1 s for     *                       reliable prediction.     * @param features      extracted audio features (intonation, rate, filler,     *                       silence). Pass [AudioFeatures.unknown] if feature     *                       extraction isn't available — the predictor will     *                       fall back to VAP-only or silence-only.     * @return an [EndOfSpeechPrediction] with the boolean verdict + confidence.     */    fun predictEndOfSpeech(        audioContext: ShortArray,        features: AudioFeatures,    ): EndOfSpeechPrediction {        // 1. Try VAP ML model (primary).        val vap = vapBackend        if (vap != null && vap.isReady && audioContext.size >= minVapContextSamples()) {            val vapProbability = runCatching { vap.predict(audioContext) }                .onFailure { Timber.tag(TAG).w("VAP inference failed, falling back to heuristic.", it) }                .getOrNull()            if (vapProbability != null) {                val willEnd = vapProbability >= config.vapConfidenceThreshold                // Combine VAP with heuristic for borderline cases.                val heuristicScore = computeHeuristicScore(features)                val combined = if (vapProbability in 0.4f..0.8f) {                    // Borderline — blend with heuristic.                    (vapProbability * 0.7f) + (heuristicScore * 0.3f)                } else {                    vapProbability                }                return EndOfSpeechPrediction(                    willEndWithin1Second = willEnd || heuristicScore >= config.heuristicThreshold,                    confidence = combined,                    source = PredictionSource.VAP,                )            }        }        // 2. Fall back to heuristic (always available).        val heuristicScore = computeHeuristicScore(features)        return EndOfSpeechPrediction(            willEndWithin1Second = heuristicScore >= config.heuristicThreshold,            confidence = heuristicScore,            source = PredictionSource.HEURISTIC,        )    }    // ──────────────────────────────────────────────────────────────────────    /**     * Compute the heuristic end-of-speech score from audio features.     *     * Weighted combination per §12:     *  - Intonation drop  × 0.30     *  - Rate slowdown    × 0.20     *  - Filler word      × 0.20     *  - Silence duration × 0.30     *     * Returns a score in [0, 1].     */    internal fun computeHeuristicScore(features: AudioFeatures): Float {        val intonationDrop = features.intonationDropScore  // 0–1        val rateSlowdown = features.rateSlowdownScore      // 0–1        val fillerWord = if (features.hasFillerWord) 1f else 0f        val silenceScore = silenceScore(features.silenceMs)        return (intonationDrop * 0.30f) +            (rateSlowdown * 0.20f) +            (fillerWord * 0.20f) +            (silenceScore * 0.30f)    }    /**     * Map silence duration to a 0–1 score.     *     *  - 0 ms silence → 0.0 (definitely not end)     *  - 200 ms → 0.4 (possible end)     *  - 500 ms → 1.0 (definitely end, per §6 STT silence timeout)     *  - > 500 ms → 1.0 (saturated)     */    internal fun silenceScore(silenceMs: Long): Float {        if (silenceMs <= 0) return 0f        if (silenceMs >= config.silenceMsForEnd) return 1f        return silenceMs.toFloat() / config.silenceMsForEnd    }    /** Minimum audio context (in samples) for VAP inference. */    private fun minVapContextSamples(): Int = AudioCapturePipeline.SAMPLE_RATE  // 1 second    private companion object {        private const val TAG = "EndOfSpeechPredictor"    }}// ──────────────────────────────────────────────────────────────────────────/** * Extracted audio features used by the heuristic predictor. * * All scores are in [0, 1] where 1.0 = strong signal that user is ending. * * @param intonationDropScore  0–1, normalized pitch drop in the last 500 ms. * @param rateSlowdownScore    0–1, normalized speaking-rate decrease. * @param hasFillerWord        true if a known filler ("so", "that's it", etc.) *                              was detected in the last partial STT result. * @param silenceMs            silence duration since last voiced chunk. */data class AudioFeatures(    val intonationDropScore: Float,    val rateSlowdownScore: Float,    val hasFillerWord: Boolean,    val silenceMs: Long,) {    init {        require(intonationDropScore in 0f..1f) {            "intonationDropScore must be in [0,1], got $intonationDropScore"        }        require(rateSlowdownScore in 0f..1f) {            "rateSlowdownScore must be in [0,1], got $rateSlowdownScore"        }        require(silenceMs >= 0) { "silenceMs must be non-negative" }    }    companion object {        /** Sentinel features when feature extraction isn't available.         *  Forces the predictor to rely on VAP or silence alone. */        val UNKNOWN = AudioFeatures(            intonationDropScore = 0f,            rateSlowdownScore = 0f,            hasFillerWord = false,            silenceMs = 0L,        )    }}// ──────────────────────────────────────────────────────────────────────────/** Result of an end-of-speech prediction. */data class EndOfSpeechPrediction(    /** True if the user is likely to stop speaking within 1 second. */    val willEndWithin1Second: Boolean,    /** Confidence in the prediction (0.0–1.0). */    val confidence: Float,    /** Which predictor produced this result. */    val source: PredictionSource,) {    init {        require(confidence in 0f..1f) { "confidence must be in [0,1], got $confidence" }    }}// ──────────────────────────────────────────────────────────────────────────/** Which predictor produced the end-of-speech result. */enum class PredictionSource {    /** VAP ML model (primary, 95% accuracy). */    VAP,    /** Heuristic combination (fallback, 75% accuracy). */    HEURISTIC,}// ──────────────────────────────────────────────────────────────────────────/** * ONNX Runtime backend for the VAP (Voice Activity Projection) model. * * Real implementation lives in :native:vap (ships Year 3 per §24 Year-3 * roadmap). Tests inject a fake to verify the prediction pipeline without * needing ONNX Runtime. * * The model takes 3 s of 16 kHz audio (48,000 samples) and outputs a single * probability that the user will stop speaking within 1 s. */interface VapBackend {    /**     * Run VAP inference on the audio context.     *     * @param audioContext  recent audio (3 s @ 16 kHz = 48,000 samples).     * @return probability (0.0–1.0) that the user will stop within 1 s.     * @throws Throwable if inference fails (caller catches and falls back).     */    fun predict(audioContext: ShortArray): Float    /** Whether the ONNX model is loaded and ready. */    val isReady: Boolean    /** Release ONNX resources. */    fun release()}
